-- B12 Steak yönetilebilir restoran menüsü
create table menu_categories (id bigint generated by default as identity primary key, slug text unique not null, title_tr text not null, title_en text, sort_order int default 0, is_active boolean default true, created_at timestamptz default now());
create table menu_sections (id bigint generated by default as identity primary key, category_id bigint not null references menu_categories(id) on delete cascade, title_tr text not null, title_en text, sort_order int default 0, is_active boolean default true);
create table menu_items (id bigint generated by default as identity primary key, section_id bigint not null references menu_sections(id) on delete cascade, name_tr text not null, name_en text, description_tr text, description_en text, price numeric(10,2) not null default 0, image_path text, tags text[] default '{}', sort_order int default 0, is_active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
alter table menu_categories enable row level security; alter table menu_sections enable row level security; alter table menu_items enable row level security;
create policy "public active categories" on menu_categories for select using (is_active=true);
create policy "public active sections" on menu_sections for select using (is_active=true);
create policy "public active items" on menu_items for select using (is_active=true);